INSERT INTO audit_review_record (
    record_id, audit_type, target_id, action, from_status,
    to_status, reason, reviewer_id, create_time
) VALUES (
    #{recordId}, #{auditType}, #{targetId}, #{action}, #{fromStatus},
    #{toStatus}, #{reason}, #{reviewerId}, #{createTime}
)

mapper.select:
SELECT r.id, r.record_id, r.audit_type, r.target_id, r.action, r.from_status, r.to_status, r.reason, r.reviewer_id, r.create_time, CASE WHEN r.audit_type = 'project' THEN p.title WHEN r.audit_type = 'company' THEN cu.nickname ELSE NULL END AS target_name, ru.nickname AS reviewer_name FROM audit_review_record r LEFT JOIN project p ON r.audit_type = 'project' AND r.target_id = p.project_id LEFT JOIN user cu ON r.audit_type = 'company' AND r.target_id = cu.user_id LEFT JOIN user ru ON r.reviewer_id = ru.user_id
r.audit_type = #{auditType}
AND r.target_id = #{targetId}
AND r.action = #{action}
ORDER BY r.create_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM audit_review_record r


        r.audit_type = #{auditType}


        AND r.target_id = #{targetId}


        AND r.action = #{action}
